import com.sun.net.httpserver.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.concurrent.*;
/** Player-facing confirmation and sign-in page; independent from administrator access. */
final class AccountWeb {
 final GunnyServer s;final boolean test;record Session(String id,long expires){}final Map<String,Session> sessions=new ConcurrentHashMap<>();
 AccountWeb(GunnyServer server,boolean testing){s=server;test=testing||server.store instanceof CloudStore.Memory;}
 String cookie(HttpExchange x){String h=x.getRequestHeaders().getFirst("Cookie");if(h!=null)for(String part:h.split(";")){String[] p=part.trim().split("=",2);if(p.length==2&&p[0].equals("gunny_player"))return p[1];}return "";}
 void json(HttpExchange x,int code,Object value)throws IOException{byte[] b=Json.write(value).getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(code,b.length);x.getResponseBody().write(b);}
 void handle(HttpExchange x)throws IOException{try{Headers h=x.getResponseHeaders();h.set("Cache-Control","no-store");h.set("Referrer-Policy","no-referrer");h.set("X-Content-Type-Options","nosniff");h.set("Content-Security-Policy","default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");String path=x.getRequestURI().getPath(),method=x.getRequestMethod();
 if(!path.startsWith("/auth/api/")){String file=path.equals("/")||path.equals("/auth/confirmed")||path.equals("/account")||path.equals("/account/")?"index.html":path.equals("/account/app.js")?"app.js":path.equals("/account/style.css")?"style.css":"";if(file.isEmpty()){json(x,404,Map.of("error","Không tìm thấy"));return;}if(!method.equals("GET")&&!method.equals("HEAD")){x.sendResponseHeaders(405,-1);return;}byte[] b=Files.readAllBytes(Path.of("public/account",file));h.set("Content-Type",file.endsWith("js")?"text/javascript; charset=utf-8":file.endsWith("css")?"text/css; charset=utf-8":"text/html; charset=utf-8");x.sendResponseHeaders(200,method.equals("HEAD")?-1:b.length);if(!method.equals("HEAD"))x.getResponseBody().write(b);return;}
 String op=path.substring(10),ip=x.getRemoteAddress().getAddress().getHostAddress();
 if(method.equals("GET")&&op.equals("session")){Session session=sessions.get(cookie(x));if(session==null||session.expires<System.currentTimeMillis()){json(x,401,Map.of("error","Hãy đăng nhập"));return;}CloudStore.Profile p=s.store.profile(session.id);json(x,200,Map.of("name",p.name,"id",p.publicId,"coins",p.coins,"money",p.shoppingMoney));return;}
 if(!method.equals("POST")||!"application/json".equalsIgnoreCase(x.getRequestHeaders().getFirst("Content-Type"))){json(x,405,Map.of("error","Yêu cầu không hợp lệ"));return;}
 String origin=x.getRequestHeaders().getFirst("Origin"),host=x.getRequestHeaders().getFirst("Host");URI u=origin==null?null:URI.create(origin);if(u==null||!u.getRawAuthority().equalsIgnoreCase(host)||!u.getScheme().equals("https")&&!(test&&u.getScheme().equals("http"))){json(x,403,Map.of("error","Yêu cầu không hợp lệ"));return;}
 if(!s.limit("player-web:"+ip,12)){json(x,429,Map.of("error","Thử lại sau một phút"));return;}byte[] b=x.getRequestBody().readNBytes(8193);if(b.length>8192)throw new IllegalArgumentException("Dữ liệu quá dài");Map<String,Object> data=Json.obj(Json.parse(new String(b,StandardCharsets.UTF_8)));
 if(op.equals("verify")){String token=Json.str(data,"token_hash");if(!token.matches("[A-Za-z0-9_-]{20,200}"))throw new IllegalArgumentException("Liên kết không hợp lệ");s.store.verifyEmail(token);json(x,200,Map.of("confirmed",true));return;}
 if(op.equals("verify-access")){String token=Json.str(data,"access_token");if(token.isEmpty()||token.length()>4096)throw new IllegalArgumentException("Liên kết không hợp lệ");s.store.verifyEmailAccess(token);json(x,200,Map.of("confirmed",true));return;}
 if(op.equals("logout")){sessions.remove(cookie(x));h.add("Set-Cookie","gunny_player=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0"+(test?"":"; Secure"));json(x,200,Map.of("ok",true));return;}
 if(!op.equals("login")){json(x,404,Map.of("error","Không tìm thấy"));return;}
 String email=Json.str(data,"email").trim().toLowerCase(Locale.ROOT),pw=Json.str(data,"password");if(!email.contains("@")||email.length()>254||pw.length()<8||pw.length()>128)throw new IllegalArgumentException("Nhập email và mật khẩu từ 8 ký tự");CloudStore.Login login=s.store.login(email,pw);List<?> notices=s.admin.login(login.userId);CloudStore.Profile p=s.store.profile(login.userId);long now=System.currentTimeMillis();sessions.entrySet().removeIf(e->e.getValue().expires<now);if(sessions.size()>=1024)throw new IllegalArgumentException("Máy chủ đang đầy");byte[] random=new byte[32];s.random.nextBytes(random);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(random);int lifetime=Math.max(60,Math.min(3600,login.lifetime));sessions.put(token,new Session(login.userId,now+lifetime*1000L));h.add("Set-Cookie","gunny_player="+token+"; HttpOnly; SameSite=Strict; Path=/; Max-Age="+lifetime+(test?"":"; Secure"));json(x,200,Map.of("name",p.name,"id",p.publicId,"coins",p.coins,"money",p.shoppingMoney,"notices",notices));
 }catch(IllegalArgumentException e){json(x,400,Map.of("error",e.getMessage()));}catch(Exception e){json(x,503,Map.of("error","Chưa xử lý được. Thử đăng nhập bằng email đã xác nhận hoặc yêu cầu thư xác nhận mới."));}finally{x.close();}}
}
